  return (
    <div className="productCard">
      <img src={image} alt="bild" />
      <p className="prodName">{name}</p>
      <div className="action">
        <p>${price}</p>
        {isInCart ? (<button onClick={handleAdd}>Add to cart</button>) : <button className="remove" onClick={handleRemove}>Remove from cart</button>

}
      </div>
    </div>
  );
}
